using Lastlight.Core;
public static class PhysicalEdges
{
 public static void Run(Definitions d,string output)
 {
  Directory.CreateDirectory(output);void Require(bool v,string m){if(!v)throw new Exception(m);}void Steps(World w,int n){for(int i=0;i<n;i++)w.Step(d);}void Command(World w,WorldCommand c){var r=w.Apply(c,d);Require(r.Accepted,r.Message);}long Spawn(World w,string id,int x,int y,int n=1){w.CellAt(x,y,0).TerrainId="soil";var r=w.Apply(new(CommandKind.Spawn,DefinitionId:id,X:x,Y:y,Quantity:n),d);Require(r.Accepted,r.Message);return r.EntityId;}World Fixture(){var w=VerticalWorldGenerator.Create(d,729);w.EnablePhysical(d);w.Physical.Water.Clear();w.Physical.InjectedWater=0;foreach(var p in w.Colony.People.Values)p.Drafted=true;return w;}
  var battery=Fixture();long gen=Spawn(battery,"generator",20,20);long stored=Spawn(battery,"f-battery",22,20);long lamp=Spawn(battery,"sunlamp",23,20);battery.Physical.Devices[gen].Fuel=20;Steps(battery,600);double charge=battery.Physical.Devices[stored].Charge;Require(charge>0,"Battery never stored surplus.");Command(battery,new(CommandKind.PhysicalAction,gen,Text:"toggle"));Steps(battery,300);Require(battery.DevicePowered(lamp)&&battery.Physical.Devices[stored].Charge<charge,"Storage did not cover generation outage.");Steps(battery,6000);Require(!battery.DevicePowered(lamp)&&battery.Physical.Devices[stored].Charge==0,"Depleted battery fabricated power.");battery.Validate(d);Console.WriteLine("PASS F03 edge: real battery charge/discharge, finite backup and depletion outage");
  var filter=Fixture();for(int y=19;y<=21;y++)for(int x=19;x<=22;x++)filter.CellAt(x,y,0).TerrainId="stone";long cleaner=Spawn(filter,"f-filter",21,20);filter.CellAt(20,20,0).TerrainId="soil";filter.AddWater(filter.Index(20,20),1,.8,d);long energy=Spawn(filter,"generator",22,20);filter.Physical.Devices[energy].Fuel=30;Steps(filter,900);Require(filter.Physical.FilteredContaminant>0&&filter.WaterConcentration(filter.Index(20,20))<.2,"Powered filter failed to retain contaminant mass.");filter.Validate(d);Console.WriteLine("PASS F01 edge: powered filter lowers concentration while retaining removed mass in conservation ledger");
  var hunt=Fixture();long hunter=hunt.Colony.People.Keys.First();var prey=hunt.Entities.First(e=>e.DefinitionId=="grazer");prey.X=40;prey.Y=40;hunt.Find(hunter)!.X=39;hunt.Find(hunter)!.Y=40;hunt.Body(hunter)!.WeaponId="spear";hunt.Colony.People[hunter].Skills[4]=20;Command(hunt,new(CommandKind.Draft,hunter,Quantity:0));Array.Fill(hunt.Colony.People[hunter].Schedule,ScheduleActivity.Work);hunt.Colony.People[hunter].Priorities[7]=1;Command(hunt,new(CommandKind.Designate,DefinitionId:"Hunt",X:40,Y:40));
  for(int i=0;i<20000&&hunt.Body(prey.Id) is {Dead:false};i++)hunt.Step(d);Steps(hunt,60);Require(hunt.Body(prey.Id)!.Dead&&hunt.Resources("f-meat").Total==6,"Hunting failed to produce a single physical meat yield.");double reserve=hunt.Physical.Population;Steps(hunt,600);Require(hunt.Resources("f-meat").Total==6&&hunt.Physical.Population==reserve,"Death produced repeated meat/abundance changes.");hunt.Validate(d);Console.WriteLine("PASS F05 edge: autonomous armed hunting, one corpse yield and one regional abundance reduction");
  var disease=Fixture();var animal=disease.Entities.First(e=>e.DefinitionId=="grazer");animal.X=40;animal.Y=40;disease.CellAt(40,40,0).TerrainId="soil";disease.TryClaim("animal:"+animal.Id,disease.Colony.People.Keys.First());disease.AddWater(disease.Index(40,40),1,.8,d);Steps(disease,900);Require(disease.Physical.Animals[animal.Id].Disease>0,"Contaminated water did not cause animal disease.");disease.Validate(d);Console.WriteLine("PASS F05 edge: animal contamination exposure changes persistent disease state");
  var sustained=PhysicalWorldGenerator.Create(d,74219);for(int i=0;i<World.TicksPerDay*3;i++)sustained.Step(d);sustained.Validate(d);Require(sustained.Colony.People.Keys.All(id=>sustained.Body(id) is {Dead:false}),"Physical camp lost a resident during three-day run.");Require(sustained.Autonomy.Harvested>0&&sustained.Resources("meal").Total+sustained.Resources("grain").Total>0,"Physical farm/food loop failed.");SaveStore.Write(Path.Combine(output,"physical-depth-day-three.lastlight"),sustained,new ViewState{CameraX=64,CameraY=64,OpenTab="Engineering"},d);var reloaded=SaveStore.Read(Path.Combine(output,"physical-depth-day-three.lastlight"),d).World;Steps(sustained,900);Steps(reloaded,900);Require(SaveStore.Fingerprint(sustained)==SaveStore.Fingerprint(reloaded),"Sustained physical save diverged.");Console.WriteLine("PASS F sustained: three simulated days, five surviving residents, harvest/food, mass ledger and deterministic continuation");
 }
}
